  public static void RequireAdmin(){if(Environment.OSVersion.Platform!=PlatformID.Win32NT||!Environment.Is64BitProcess||!Environment.Is64BitOperatingSystem)throw new IOException("Reikia Windows x64 ir 64 bitų diegimo proceso.");if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))throw new UnauthorizedAccessException("Reikia administratoriaus UAC patvirtinimo.");using(var key=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64).OpenSubKey("SOFTWARE\\Microsoft\\NET Framework Setup\\NDP\\v4\\Full")){if(key==null||Convert.ToInt32(key.GetValue("Release",0))<528040)throw new IOException("Reikia .NET Framework 4.8.");}}
  static void NoLinkParent(string path){string p=Path.GetFullPath(path);while(p!=null){if(Directory.Exists(p)||File.Exists(p))FolderMonitor.NoLinks(p);p=Path.GetDirectoryName(p);}}
  static void Root(string path){NoLinkParent(path);if(!Directory.Exists(path)){Directory.CreateDirectory(path);Protect(path,null,false,false);return;}var acl=Directory.GetAccessControl(path);string owner=acl.GetOwner(typeof(SecurityIdentifier)).Value;if(owner!="S-1-5-32-544"&&owner!="S-1-5-18")throw new IOException("Ankstesnis paslaugos aplankas nepriklauso administratoriui; jis neperrašytas.");foreach(FileSystemAccessRule rule in acl.GetAccessRules(true,true,typeof(SecurityIdentifier))){string sid=rule.IdentityReference.Value;var writable=FileSystemRights.Write|FileSystemRights.Delete|FileSystemRights.ChangePermissions|FileSystemRights.TakeOwnership;if(rule.AccessControlType==AccessControlType.Allow&&(rule.FileSystemRights&writable)!=0&&sid!="S-1-5-32-544"&&sid!="S-1-5-18")throw new IOException("Paslaugos šaknies rašymo teisės nesaugios; reikia peržiūros.");}}
