   string version=Path.Combine(ProgramRoot,"versions",m.Version+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(version);foreach(var f in m.Files){stop.ThrowIfCancellationRequested();File.Copy(Path.Combine(source,f.Name),Path.Combine(version,f.Name));}File.Copy(Path.Combine(source,"release.json"),Path.Combine(version,"release.json"));if(!string.IsNullOrEmpty(pin))File.Copy(Path.Combine(source,"publisher.cer"),Path.Combine(version,"publisher.cer"));VerifyPackage(version,floor,pin,beta);
   string oldFloor=File.Exists(floorPath)?File.ReadAllText(floorPath):null,oldPin=File.Exists(pinPath)?File.ReadAllText(pinPath):null;string oldDirectory=null,oldReceipt=null;object oldVersion=null;using(var key=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64).OpenSubKey("Software\\SARGONService")){if(key!=null){oldDirectory=key.GetValue("CurrentDirectory") as string;oldReceipt=key.GetValue("LastSetupId") as string;oldVersion=key.GetValue("Version");}}
