    string oldDb=Path.Combine(privateRoot,"clamav","database"),newDb=Path.Combine(DataRoot,"Databases");if(Directory.Exists(oldDb)&&!Directory.EnumerateFiles(newDb).Any()){FolderMonitor.NoLinks(oldDb);foreach(string src in Directory.EnumerateFiles(oldDb).Where(f=>f.EndsWith(".cvd",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".cld",StringComparison.OrdinalIgnoreCase)).Take(16)){stop.ThrowIfCancellationRequested();FolderMonitor.NoLinks(src);string dst=Path.Combine(newDb,Path.GetFileName(src));using(var input=new FileStream(src,FileMode.Open,FileAccess.Read,FileShare.Read))using(var output=new FileStream(dst,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[65536];int count;while((count=input.Read(buffer,0,buffer.Length))>0){stop.ThrowIfCancellationRequested();output.Write(buffer,0,count);}output.Flush(true);}}}
    string config=Path.Combine(ProgramRoot,"service-config.json");if(!File.Exists(config))Data.Atomic(config,Data.Json().Serialize(new {Roots=new[]{Path.GetPathRoot(Environment.SystemDirectory)},AutomaticUpdates=true,DetectionControl=false,PeriodHours=24,PauseOnBattery=true,PauseWhenBusy=true,UseCleanCache=true}));
    ProtectConfig(config,sid);
