    progress("Paleidžiama paslauga ir laukiama jos veiklos signalo…");long begin=DateTime.UtcNow.Ticks;using(var svc=new ServiceController(Name))svc.Start();bool ready=false;DateTime until=DateTime.UtcNow.AddSeconds(60);while(DateTime.UtcNow<until){stop.ThrowIfCancellationRequested();Thread.Sleep(500);try{var s=ServiceHeartbeat.Read(Path.Combine(DataRoot,"Public","status.json"));if(s.At>=begin&&s.Version==m.Version&&s.EngineReady&&s.ManualControlReady&&s.State!="STARTING"&&!s.State.StartsWith("ERROR")&&!s.State.StartsWith("STOPPED")){ready=true;break;}}catch(IOException){}catch(ArgumentException){}}
