  public static void RequestDatabaseUpdate(bool allowBattery,Action<string> progress,System.Threading.CancellationToken stop){RequireAdmin();using(var mutex=new Mutex(false,"Global\\SARGON.Setup.v1")){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("Kitas paslaugos paruošimas jau vyksta.");string path=Path.Combine(DataRoot,"Public","status.json");FolderMonitor.NoLinks(path);var before=ServiceHeartbeat.Read(path);if(!ServiceHeartbeat.Fresh(before,DateTime.UtcNow.Ticks)||before.Version<49||!before.ManualControlReady)throw new IOException("Rankiniam atnaujinimui reikia šviežios 0.49 ar naujesnės paslaugos su apsaugotomis komandų teisėmis. Įdiekite bendro diegiklio paslaugos dalį.");if(before.State=="UPDATING_DATABASE"||before.State=="MANUAL_UPDATING_DATABASE"||before.ManualPending||before.ManualRunning)throw new IOException("Kita atnaujinimo užklausa jau laukia arba vykdoma. Jos būseną tikrinkite parengties lange.");stop.ThrowIfCancellationRequested();using(var service=new ServiceController(Name)){if(service.Status!=ServiceControllerStatus.Running)throw new IOException("Paslauga neveikia.");service.ExecuteCommand(allowBattery?129:128);}progress("Užklausa perduota paslaugai. Laukiama eilės, bazių ir neutralaus failo kontrolės. Langas nekopijuoja ir neperrašo bazių pats.");DateTime until=DateTime.UtcNow.AddMinutes(20);string previous=null;while(DateTime.UtcNow<until){stop.ThrowIfCancellationRequested();Thread.Sleep(1000);var current=ServiceHeartbeat.Read(path);if(!ServiceHeartbeat.Fresh(current,DateTime.UtcNow.Ticks))throw new IOException("Paslaugos signalas paseno; atnaujinimo baigtis nepatvirtinta.");if(current.RunId!=before.RunId)throw new IOException("Paslauga persileido; šios užklausos baigtis nepatvirtinta.");if(current.State!=previous){progress(current.State+" "+UpdateRequestPolicy.Explain(current.State));previous=current.State;}if(UpdateRequestPolicy.Completed(current,before.RunId,before.ManualCompleted,DateTime.UtcNow.Ticks)){if(current.ManualResult!="SUCCESS"||!current.DatabaseReady||current.DatabaseProbeAt<=0){string journal=Path.Combine(DataRoot,"Private","last-update.txt");if(File.Exists(journal)){FolderMonitor.NoLinks(journal);using(var input=File.OpenRead(journal))progress(Data.CleanLog(System.Text.Encoding.UTF8.GetString(Data.Bounded(input,65536,null))));}throw new IOException("Paslauga baigė bandymą, bet bazių ir neutralaus runtime patikros nepatvirtino. Žurnalas: ProgramData/SARGONService/Private/last-update.txt");}progress("Bazės atnaujintos ir neutralus kontrolinis failas patikrintas. Tai nėra visų grėsmių aptikimo garantija.");return;}}throw new IOException("Laukimo riba. Užklausa gali likti vykdoma; patikrinkite paslaugos būseną. Nekurkite pakartotinių užklausų.");}finally{if(held)mutex.ReleaseMutex();}}}
  public static void Remove(Action<string> progress,string requestId=null){using(var mutex=new Mutex(false,"Global\\SARGON.Setup.v1")){bool held=false;try{try{held=mutex.WaitOne(0);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("Kitas SARGON diegimas jau vyksta.");RemoveCore(progress,requestId);}finally{if(held)mutex.ReleaseMutex();}}}
  static void RemoveCore(Action<string> progress,string requestId){if(requestId!=null&&!Guid.TryParse(requestId,out var ignored))throw new IOException("Netinkamas užklausos ID.");RequireAdmin();progress("Stabdoma ir išregistruojama SARGON paslauga…");Stop();using(var service=Existing()){if(service!=null){using(var result=service.InvokeMethod("Delete",null,null)){if(Convert.ToUInt32(result["ReturnValue"])!=0)throw new IOException("Paslaugos išregistruoti nepavyko.");}}}using(var key=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Registry64)){key.DeleteSubKeyTree("Software\\SARGONService",false);if(requestId!=null)using(var receipt=key.CreateSubKey("Software\\SARGONService"))receipt.SetValue("LastRemovedId",requestId);}progress("Paslaugos registracija pašalinta. Žurnalai, bazės ir atkuriamos kopijos netrinami.");}
  static void PrepareEngine(Action<string> progress,CancellationToken stop){progress("Atsisiunčiamas oficialus ClamAV variklis (apie 200 MB)…");string stage=Path.Combine(ProgramRoot,"engine-stage-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(stage);try{string zip=Path.Combine(stage,"engine.zip");ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create("https://www.clamav.net/downloads/production/clamav-1.4.6.win.x64.zip");request.Timeout=30000;request.ReadWriteTimeout=30000;using(stop.Register(()=>request.Abort()))using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=new FileStream(zip,FileMode.CreateNew,FileAccess.Write)){byte[] b=new byte[65536];long total=0;int n;while((n=input.Read(b,0,b.Length))>0){stop.ThrowIfCancellationRequested();if((total+=n)>251658240)throw new IOException("Atsisiuntimo dydžio riba.");output.Write(b,0,n);}}
    using(var input=File.OpenRead(zip))using(var sha=SHA256.Create())if(Data.Hex(sha.ComputeHash(input))!=EngineArchiveSha)throw new IOException("Oficialaus archyvo SHA256 nesutampa.");progress("Tikrinamas ir išpakuojamas variklis…");string expanded=Path.Combine(stage,"expanded");Directory.CreateDirectory(expanded);using(var zipStream=File.OpenRead(zip))using(var archive=new ZipArchive(zipStream,ZipArchiveMode.Read,false)){if(archive.Entries.Count>4096)throw new IOException("Archyvo failų riba.");long total=0;foreach(var entry in archive.Entries){stop.ThrowIfCancellationRequested();string target=Path.GetFullPath(Path.Combine(expanded,entry.FullName.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(expanded+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||((entry.ExternalAttributes>>16)&0xF000)==0xA000||(total+=entry.Length)>1073741824L)throw new IOException("Nesaugus archyvo kelias ar apimtis.");if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(target);continue;}Directory.CreateDirectory(Path.GetDirectoryName(target));using(var source=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[65536];long written=0;int n;while((n=source.Read(buffer,0,buffer.Length))>0){stop.ThrowIfCancellationRequested();if((written+=n)>entry.Length)throw new IOException("Archyvo įrašo dydis nepatvirtintas.");output.Write(buffer,0,n);}if(written!=entry.Length)throw new IOException("Archyvo įrašas nepilnas.");}}}
    string bin=Path.Combine(expanded,"clamav-1.4.6.win.x64");if(!File.Exists(Path.Combine(bin,"clamscan.exe"))||!File.Exists(Path.Combine(bin,"freshclam.exe")))throw new IOException("Trūksta variklio failų.");var files=Directory.EnumerateFiles(expanded,"*",SearchOption.AllDirectories).Select(f=>{FolderMonitor.NoLinks(f);using(var input=File.OpenRead(f))using(var sha=SHA256.Create())return new {Name=f.Substring(expanded.Length+1),Hash=Data.Hex(sha.ComputeHash(input))};}).ToArray();Directory.Move(expanded,Path.Combine(ProgramRoot,"engine"));Data.Atomic(Path.Combine(ProgramRoot,"engine-integrity.json"),Data.Json().Serialize(files));
   }finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}
